/**
 * Meeting Esau
 * ------------
 * Jacob sends gifts ahead and bows seven times; Esau runs to meet him, and they weep. Stage: a plain at dawn, a long line of gifts, a brother running with four hundred men; fear turning to a kiss; the sun climbing over a tent camp.
 *
 * Palette 0x241a10 → 0x060402 · light: ember · hero: tent
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./jacob-kit.js.
 */

import { THREE, createScene, tent, firepit, person } from './jacob-kit.js';

const BG = 0x241a10;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 3499039102, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* camp: a circle of tents, smoke rising */
    tent(W, group, -8.5, 0, -6.3, 1.25, 0xd8c8a0, W.r() * 6);
    tent(W, group, -15.0, 0, -20.4, 1.18, 0xd8c8a0, W.r() * 6);
    tent(W, group, 1.8, 0, -22.8, 1.01, 0xd8c8a0, W.r() * 6);
    tent(W, group, 22.2, 0, -1.6, 1.13, 0xc8b088, W.r() * 6);
    firepit(W, group, 7.0, 0, -5.7, 1.0);

    /* hero: the tent */
    tent(W, group, 0, 0, 0, 1.4, 0x060402, 0.2);
    W.disc([0, 5, -10], 5, 0x2f2215, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x241a10, bend: 0.2, armR: [0.35, 0.1], armL: [-0.35, -0.1], ry: -0.66, s: 1.10 });
    person(W, group, [4.5, 0, 6], { robe: 0x060402, bend: 0.2, armR: [0.35, 0.1], armL: [-0.35, -0.1], ry: -0.04, s: 1.11 });

    return W.finish();
}

export default { build };
